const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define locations
  const victoria = ee.Geometry.Point([-97.0035, 28.8053]);
  const corpusChristi = ee.Geometry.Point([-97.3964, 27.8006]);

  // 2. Define time period
  const startDate = '2018-06-15';
  const endDate = '2018-06-23'; // Exclusive end date

  // 3. Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  // Check if collection has data
  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No precipitation data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Sum precipitation over the period (CHIRPS is in mm/day)
  const totalPrecip = chirps.select('precipitation').sum();

  // 5. Extract values for both cities
  const victoriaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: victoria,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const corpusStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: corpusChristi,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const victoriaMm = victoriaStats.precipitation;
  const corpusMm = corpusStats.precipitation;

  // 6. Validate results
  if (victoriaMm === null || victoriaMm === undefined || corpusMm === null || corpusMm === undefined) {
    console.log("Calculation failed - null values returned.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const victoriaInches = victoriaMm / 25.4;
  const corpusInches = corpusMm / 25.4;

  console.log(`Victoria rainfall: ${victoriaInches.toFixed(2)} inches (${victoriaMm.toFixed(1)} mm)`);
  console.log(`Corpus Christi rainfall: ${corpusInches.toFixed(2)} inches (${corpusMm.toFixed(1)} mm)`);

  // 7. Check if both received less than 20 inches
  if (victoriaInches < 20 && corpusInches < 20) {
    console.log("Both cities received less than 20 inches of rainfall.");
    console.log("<answer>A</answer>");
  } else {
    console.log("At least one city received 20 inches or more of rainfall.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
